1	package stowage
2	
3	import (
4		"reflect"
5		"strings"
6		"testing"
7	)
8	
9	// 本组回归测试保护这条使用过程：预览通过后，货物又被另一笔成功的调整
10	// 移走（或卸下、或直接移到原清单的目标舱位），不重新预览、直接按原
11	// 清单正式提交。预览只表示当时的预计配载，不预留舱位，也不固定货物
12	// 的来源；正式移动必须按提交时货物实际所在舱位处理。正式提交一律使用
13	// 尚未成功使用过的调整编号，避免把已成功编号返回的历史结果误当成执行
14	// 了一次新移动。
15	
16	// setupStaleMoveScenario 建立共同的初始场景：
17	// C1（甲舱）、C2（乙舱）、C3（丙舱）承重均为 100 千克；G1 重 30 千克、
18	// 目的地 X、不允许混装，已装入 C1；G2 重 40 千克、目的地 X、不允许混装，
19	// 已装入 C2，作为全程不参与操作的其他货物。
20	//
21	// 返回登记处、“把 G1 从 C1 移到 C2”的原清单，以及对该清单的可提交预览
22	// （C1 预计清空，C2 预计含 G1、G2 共 70 千克、剩余 30 千克）。预览后
23	// 实际配载保持原样。
24	func setupStaleMoveScenario(t *testing.T) (*Registry, []Op, *PreviewResult) {
25		t.Helper()
26		r := NewRegistry()
27		for _, id := range []string{"C1", "C2", "C3"} {
28			if err := r.RegisterCompartment(id, 100); err != nil {
29				t.Fatal(err)
30			}
31		}
32		if err := r.RegisterCargo("G1", 30, "X", false); err != nil {
33			t.Fatal(err)
34		}
35		if err := r.RegisterCargo("G2", 40, "X", false); err != nil {
36			t.Fatal(err)
37		}
38		if _, err := r.Adjust("A0", []Op{
39			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
40			{Kind: OpLoad, CargoID: "G2", Target: "C2"},
41		}); err != nil {
42			t.Fatal(err)
43		}
44	
45		ops := []Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}}
46		pv, err := r.Preview(ops)
47		if err != nil {
48			t.Fatal(err)
49		}
50		if !pv.Submittable {
51			t.Fatalf("G1 30 千克移入已有 G2 40 千克的 C2 共 70 千克，应可提交: %+v", pv.Rejections)
52		}
53		if len(pv.Compartments) != 2 ||
54			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
55			t.Fatalf("原预览受影响舱位应为 C1、C2: %+v", pv.Compartments)
56		}
57		// 预览前：C1 仅 G1（30/70），C2 仅 G2（40/60）。
58		c1 := pv.Compartments[0]
59		if c1.Before.UsedWeight != 30 || c1.Before.RemainingWeight != 70 ||
60			!reflect.DeepEqual(cargoIDs(c1.Before), []string{"G1"}) {
61			t.Fatalf("原预览 C1 调整前应为 G1 一件 30/70: %+v", c1.Before)
62		}
63		c2 := pv.Compartments[1]
64		if c2.Before.UsedWeight != 40 || c2.Before.RemainingWeight != 60 ||
65			!reflect.DeepEqual(cargoIDs(c2.Before), []string{"G2"}) {
66			t.Fatalf("原预览 C2 调整前应为 G2 一件 40/60: %+v", c2.Before)
67		}
68		// 预览后：C1 清空；C2 含 G1、G2 共 70 千克、剩余 30 千克。
69		if c1.After.UsedWeight != 0 || c1.After.RemainingWeight != 100 ||
70			len(c1.After.Cargo) != 0 {
71			t.Fatalf("原预览 C1 预计应清空: %+v", c1.After)
72		}
73		if c2.After.UsedWeight != 70 || c2.After.RemainingWeight != 30 ||
74			!reflect.DeepEqual(cargoIDs(c2.After), []string{"G1", "G2"}) {
75			t.Fatalf("原预览 C2 预计应含 G1、G2 共 70 千克、剩余 30 千克: %+v", c2.After)
76		}
77	
78		// 预览只读：实际配载仍保持原样，C3 本来就空。
79		gotC1, _ := r.Compartment("C1")
80		if gotC1.UsedWeight != 30 || gotC1.RemainingWeight != 70 ||
81			!reflect.DeepEqual(cargoIDs(*gotC1), []string{"G1"}) {
82			t.Fatalf("预览后 C1 应保持 G1 一件 30/70: %+v", gotC1)
83		}
84		gotC2, _ := r.Compartment("C2")
85		if gotC2.UsedWeight != 40 || gotC2.RemainingWeight != 60 ||
86			!reflect.DeepEqual(cargoIDs(*gotC2), []string{"G2"}) {
87			t.Fatalf("预览后 C2 应保持 G2 一件 40/60: %+v", gotC2)
88		}
89		g1, _ := r.Cargo("G1")
90		if !g1.Loaded || g1.CompartmentID != "C1" {
91			t.Fatalf("预览后 G1 应仍在 C1: %+v", g1)
92		}
93		return r, ops, pv
94	}
95	
96	// assertStaleMoveSnapshot 断言旧预览快照始终保留最初的内容：可提交、
97	// 货物变化为 C1 到 C2、受影响舱位只有 C1 与 C2，前后清单与重量都是
98	// 预览当时的配载，不被后续移动、卸下或正式提交改写。
99	func assertStaleMoveSnapshot(t *testing.T, pv *PreviewResult) {
100		t.Helper()
101		if !pv.Submittable || len(pv.Rejections) != 0 {
102			t.Fatalf("旧预览应仍为可提交且无拒绝原因: %+v", pv)
103		}
104		wantChanges := []CargoChange{{CargoID: "G1", From: "C1", To: "C2"}}
105		if !reflect.DeepEqual(pv.CargoChanges, wantChanges) {
106			t.Fatalf("旧预览的货物变化不应被改写: %+v want %+v", pv.CargoChanges, wantChanges)
107		}
108		if len(pv.Compartments) != 2 ||
109			pv.Compartments[0].ID != "C1" || pv.Compartments[1].ID != "C2" {
110			t.Fatalf("旧预览的受影响舱位不应被改写: %+v", pv.Compartments)
111		}
112		c1 := pv.Compartments[0]
113		if !reflect.DeepEqual(cargoIDs(c1.Before), []string{"G1"}) ||
114			c1.Before.UsedWeight != 30 || c1.Before.RemainingWeight != 70 {
115			t.Fatalf("旧预览 C1 的调整前配载不应被改写: %+v", c1.Before)
116		}
117		if len(c1.After.Cargo) != 0 || c1.After.UsedWeight != 0 || c1.After.RemainingWeight != 100 {
118			t.Fatalf("旧预览 C1 的预计配载不应被改写: %+v", c1.After)
119		}
120		c2 := pv.Compartments[1]
121		if !reflect.DeepEqual(cargoIDs(c2.Before), []string{"G2"}) ||
122			c2.Before.UsedWeight != 40 || c2.Before.RemainingWeight != 60 {
123			t.Fatalf("旧预览 C2 的调整前配载不应被改写: %+v", c2.Before)
124		}
125		if !reflect.DeepEqual(cargoIDs(c2.After), []string{"G1", "G2"}) ||
126			c2.After.UsedWeight != 70 || c2.After.RemainingWeight != 30 {
127			t.Fatalf("旧预览 C2 的预计配载不应被改写: %+v", c2.After)
128		}
129		// 旧快照里的 G1 始终保留 30 千克、目的地 X、不允许混装的登记资料。
130		var g1 *CargoView
131		for i := range c2.After.Cargo {
132			if c2.After.Cargo[i].ID == "G1" {
133				g1 = &c2.After.Cargo[i]
134			}
135		}
136		if g1 == nil {
137			t.Fatalf("旧预览 C2 预计清单仍应包含 G1: %+v", c2.After.Cargo)
138		}
139		if g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
140			t.Fatalf("旧预览应保留 G1 的原始登记资料: %+v", g1)
141		}
142	}
143	
144	// TestStalePreviewSubmitAfterInterveningMoveSucceeds 覆盖核心回归：
145	// 预览把 G1（30 千克）从 C1 移到 C2 并显示可提交后，另一笔成功调整先把
146	// G1 从 C1 移到 C3，C2 仍能接收它（重量、目的地、混装许可均未改变）。
147	// 不重新预览、用未成功使用过的新编号直接提交原移动安排，应按提交时的
148	// 实际配载成功：货物变化为 C3 到 C2；C3 收回 30 千克、C2 增加 30 千克；
149	// C1 不再是受影响舱位，重量不能再次扣减。
150	func TestStalePreviewSubmitAfterInterveningMoveSucceeds(t *testing.T) {
151		r, ops, old := setupStaleMoveScenario(t)
152	
153		// 另一笔调整先把 G1 从 C1 移到 C3。
154		first := mustAdjust(t, r, "A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C3"}})
155		if !reflect.DeepEqual(first.CargoChanges, []CargoChange{{CargoID: "G1", From: "C1", To: "C3"}}) {
156			t.Fatalf("另一笔调整的货物变化应为 C1 到 C3: %+v", first.CargoChanges)
157		}
158		// 这笔调整只影响 C1 与 C3，与尚未执行的原清单目标 C2 无关。
159		if !reflect.DeepEqual(first.CompartmentChanges, []CompartmentChange{
160			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
161			{CompartmentID: "C3", WeightBefore: 0, WeightAfter: 30},
162		}) {
163			t.Fatalf("另一笔调整的舱位重量变化错误: %+v", first.CompartmentChanges)
164		}
165		g1, _ := r.Cargo("G1")
166		if !g1.Loaded || g1.CompartmentID != "C3" ||
167			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
168			t.Fatalf("另一笔调整后 G1 应带着原登记资料位于 C3: %+v", g1)
169		}
170		c3, _ := r.Compartment("C3")
171		if c3.UsedWeight != 30 || c3.RemainingWeight != 70 ||
172			!reflect.DeepEqual(cargoIDs(*c3), []string{"G1"}) {
173			t.Fatalf("另一笔调整后 C3 应含 G1 一件 30/70: %+v", c3)
174		}
175		c1, _ := r.Compartment("C1")
176		if c1.UsedWeight != 0 || len(c1.Cargo) != 0 {
177			t.Fatalf("另一笔调整后 C1 应已清空: %+v", c1)
178		}
179	
180		// 用尚未成功使用过的编号 A2 提交原清单（G1 -> C2），按提交时实际
181		// 所在的 C3 处理，应成功。
182		res, err := r.Adjust("A2", ops)
183		if err != nil {
184			t.Fatalf("G1 已在 C3 且 C2 仍可接收，提交原安排应成功: %v", err)
185		}
186		if res == nil || res.ID != "A2" {
187			t.Fatalf("应返回编号为 A2 的成功调整结果: %+v", res)
188		}
189		if !reflect.DeepEqual(res.CargoChanges, []CargoChange{{CargoID: "G1", From: "C3", To: "C2"}}) {
190			t.Fatalf("货物变化应按提交时实际位置记为 C3 到 C2: %+v", res.CargoChanges)
191		}
192		// 重量变化反映此次提交前后的实际配载：C2 40 -> 70，C3 30 -> 0。
193		// C1 不受此次移动影响，不能列为受影响舱位，也不能再次扣减。
194		if !reflect.DeepEqual(res.CompartmentChanges, []CompartmentChange{
195			{CompartmentID: "C2", WeightBefore: 40, WeightAfter: 70},
196			{CompartmentID: "C3", WeightBefore: 30, WeightAfter: 0},
197		}) {
198			t.Fatalf("舱位重量变化应为 C2 增 30、C3 收 30，且不含 C1: %+v", res.CompartmentChanges)
199		}
200	
201		// 提交后按货物查询：G1 只在 C2，登记资料不变。
202		g1, _ = r.Cargo("G1")
203		if !g1.Loaded || g1.CompartmentID != "C2" ||
204			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
205			t.Fatalf("提交后 G1 应带着原登记资料只位于 C2: %+v", g1)
206		}
207		// 按舱位查看清单：C1、C3 清空，C2 含 G1、G2 共 70 千克、剩余 30 千克。
208		c1, _ = r.Compartment("C1")
209		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
210			t.Fatalf("提交后 C1 应保持清空、已用 0 剩余 100（不能再次扣减）: %+v", c1)
211		}
212		c2, _ := r.Compartment("C2")
213		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
214			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
215			t.Fatalf("提交后 C2 应含 G1、G2 共 70 千克、剩余 30 千克: %+v", c2)
216		}
217		c3, _ = r.Compartment("C3")
218		if c3.UsedWeight != 0 || c3.RemainingWeight != 100 || len(c3.Cargo) != 0 {
219			t.Fatalf("提交后 C3 应已移除 G1、保持清空: %+v", c3)
220		}
221		// 其他货物保持原状，且货物查询与舱位清单一致。
222		g2, _ := r.Cargo("G2")
223		if !g2.Loaded || g2.CompartmentID != "C2" || g2.Weight != 40 {
224			t.Fatalf("G2 应保持原状留在 C2: %+v", g2)
225		}
226		for _, cv := range c2.Cargo {
227			cargo, _ := r.Cargo(cv.ID)
228			if !cv.Loaded || cv.CompartmentID != "C2" ||
229				cargo.CompartmentID != "C2" || cargo.Weight != cv.Weight {
230				t.Fatalf("舱位清单与货物查询对 %s 的记录不一致: 清单=%+v 查询=%+v", cv.ID, cv, cargo)
231			}
232		}
233	
234		// 已成功使用过的 A1 以原内容再次提交，只返回首次的历史结果
235		// （C1 到 C3），不按当前位置执行任何新移动：G1 必须仍在 C2。
236		again, err := r.Adjust("A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C3"}})
237		if err != nil {
238			t.Fatalf("A1 以原内容再次提交应返回首次结果: %v", err)
239		}
240		if !reflect.DeepEqual(again.CargoChanges, first.CargoChanges) ||
241			!reflect.DeepEqual(again.CompartmentChanges, first.CompartmentChanges) {
242			t.Fatalf("A1 再次提交应原样返回首次历史结果: again=%+v first=%+v", again, first)
243		}
244		g1, _ = r.Cargo("G1")
245		if !g1.Loaded || g1.CompartmentID != "C2" {
246			t.Fatalf("历史结果不能当成新移动执行，G1 应仍在 C2: %+v", g1)
247		}
248		c2, _ = r.Compartment("C2")
249		if c2.UsedWeight != 70 || !reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
250			t.Fatalf("历史结果返回后 C2 配载不应改变: %+v", c2)
251		}
252		c3, _ = r.Compartment("C3")
253		if c3.UsedWeight != 0 || len(c3.Cargo) != 0 {
254			t.Fatalf("历史结果返回后 C3 应仍清空: %+v", c3)
255		}
256	
257		// 后续移动与正式提交都不能改写保存下来的旧预览快照。
258		assertStaleMoveSnapshot(t, old)
259	}
260	
261	// TestStalePreviewSubmitAfterInterveningUnloadStateMismatch 保护不能移动的
262	// 情况之一：另一笔调整已把 G1 卸下，再提交原来的移动安排，必须返回现有
263	// 的“状态不符”错误并指出 G1，不能把移动变成重新装载；不返回成功调整
264	// 结果，错误携带本次提交编号 A2，配载保持另一笔调整完成后的状态。
265	func TestStalePreviewSubmitAfterInterveningUnloadStateMismatch(t *testing.T) {
266		r, ops, old := setupStaleMoveScenario(t)
267	
268		// 另一笔调整先把 G1 从 C1 卸下。
269		first := mustAdjust(t, r, "A1", []Op{{Kind: OpUnload, CargoID: "G1"}})
270		if !reflect.DeepEqual(first.CargoChanges, []CargoChange{{CargoID: "G1", From: "C1", To: ""}}) {
271			t.Fatalf("另一笔调整的货物变化应为 C1 卸下: %+v", first.CargoChanges)
272		}
273		if !reflect.DeepEqual(first.CompartmentChanges, []CompartmentChange{
274			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
275		}) {
276			t.Fatalf("另一笔调整的舱位重量变化错误: %+v", first.CompartmentChanges)
277		}
278		g1, _ := r.Cargo("G1")
279		if g1.Loaded || g1.CompartmentID != "" {
280			t.Fatalf("另一笔调整后 G1 应已卸下、记录保留: %+v", g1)
281		}
282	
283		// 直接提交原移动安排：状态不符，不能当成重新装入 C2。
284		res, err := r.Adjust("A2", ops)
285		se := requireError(t, err, ErrStateMismatch)
286		if res != nil {
287			t.Fatalf("货物已卸下时必须拒绝移动，不应返回成功调整结果: %+v", res)
288		}
289		if se.ID != "G1" {
290			t.Fatalf("状态不符错误应指出货物 G1，实际 ID=%q", se.ID)
291		}
292		if se.AdjustmentID != "A2" {
293			t.Fatalf("错误应携带本次提交的调整编号 A2，实际 %q", se.AdjustmentID)
294		}
295		if msg := se.Error(); !strings.Contains(msg, "G1") {
296			t.Fatalf("状态不符说明应指出货物 G1: %s", msg)
297		}
298	
299		// 配载保留另一笔调整完成后的状态：G1 仍卸下，没有被装入 C2。
300		g1, _ = r.Cargo("G1")
301		if g1.Loaded || g1.CompartmentID != "" ||
302			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
303			t.Fatalf("拒绝后 G1 应保持已卸下且登记资料不变: %+v", g1)
304		}
305		c1, _ := r.Compartment("C1")
306		if c1.UsedWeight != 0 || len(c1.Cargo) != 0 {
307			t.Fatalf("拒绝后 C1 应保持清空: %+v", c1)
308		}
309		c2, _ := r.Compartment("C2")
310		if c2.UsedWeight != 40 || c2.RemainingWeight != 60 ||
311			!reflect.DeepEqual(cargoIDs(*c2), []string{"G2"}) {
312			t.Fatalf("拒绝后 C2 应仍只有 G2 一件 40/60，不能把 G1 装进来: %+v", c2)
313		}
314	
315		// 失败不占用编号：同一编号 A2 再次提交仍得到同样的状态不符，
316		// 而不是“调整编号冲突”，配载依旧不变。
317		res2, err2 := r.Adjust("A2", ops)
318		se2 := requireError(t, err2, ErrStateMismatch)
319		if res2 != nil {
320			t.Fatalf("失败的调整不应占用编号，也不应返回成功结果: %+v", res2)
321		}
322		if se2.ID != "G1" || se2.AdjustmentID != "A2" {
323			t.Fatalf("再次提交应仍为指出 G1、携带 A2 的状态不符: %+v", se2)
324		}
325		g1, _ = r.Cargo("G1")
326		if g1.Loaded || g1.CompartmentID != "" {
327			t.Fatalf("再次失败后 G1 应仍保持卸下: %+v", g1)
328		}
329	
330		// 卸下与失败提交都不能改写保存下来的旧预览快照。
331		assertStaleMoveSnapshot(t, old)
332	}
333	
334	// TestStalePreviewSubmitAfterAlreadyAtTargetDuplicate 保护不能移动的情况
335	// 之二：另一笔调整已把 G1 移到原清单的目标 C2，再提交原安排必须返回现有
336	// 的“重复操作”错误并指出 G1，不能当作一次成功移动，也不能重复占用重量；
337	// 不返回成功调整结果，错误携带本次提交编号 A2，配载保持另一笔调整完成后
338	// 的状态。
339	func TestStalePreviewSubmitAfterAlreadyAtTargetDuplicate(t *testing.T) {
340		r, ops, old := setupStaleMoveScenario(t)
341	
342		// 另一笔调整先把 G1 从 C1 移到原清单的目标 C2。
343		first := mustAdjust(t, r, "A1", []Op{{Kind: OpMove, CargoID: "G1", Target: "C2"}})
344		if !reflect.DeepEqual(first.CargoChanges, []CargoChange{{CargoID: "G1", From: "C1", To: "C2"}}) {
345			t.Fatalf("另一笔调整的货物变化应为 C1 到 C2: %+v", first.CargoChanges)
346		}
347		if !reflect.DeepEqual(first.CompartmentChanges, []CompartmentChange{
348			{CompartmentID: "C1", WeightBefore: 30, WeightAfter: 0},
349			{CompartmentID: "C2", WeightBefore: 40, WeightAfter: 70},
350		}) {
351			t.Fatalf("另一笔调整的舱位重量变化错误: %+v", first.CompartmentChanges)
352		}
353	
354		// 再提交原移动安排：G1 已在目标舱位 C2，属于重复操作。
355		res, err := r.Adjust("A2", ops)
356		se := requireError(t, err, ErrDuplicateOp)
357		if res != nil {
358			t.Fatalf("货物已在目标舱位时必须拒绝，不应返回成功调整结果: %+v", res)
359		}
360		if se.ID != "G1" {
361			t.Fatalf("重复操作错误应指出货物 G1，实际 ID=%q", se.ID)
362		}
363		if se.AdjustmentID != "A2" {
364			t.Fatalf("错误应携带本次提交的调整编号 A2，实际 %q", se.AdjustmentID)
365		}
366		if msg := se.Error(); !strings.Contains(msg, "G1") || !strings.Contains(msg, "C2") {
367			t.Fatalf("重复操作说明应指出货物 G1 与目标舱位 C2: %s", msg)
368		}
369	
370		// 不能当作成功移动，也不能重复占用重量：G1 在 C2 清单中只出现一次，
371		// C2 已用仍为 70 千克；C1 保持清空。
372		g1, _ := r.Cargo("G1")
373		if !g1.Loaded || g1.CompartmentID != "C2" ||
374			g1.Weight != 30 || g1.Destination != "X" || g1.AllowMixed {
375			t.Fatalf("拒绝后 G1 应仍只位于 C2、登记资料不变: %+v", g1)
376		}
377		c2, _ := r.Compartment("C2")
378		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
379			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
380			t.Fatalf("拒绝后 C2 应仍只含 G1、G2 共 70 千克，重量不能重复占用: %+v", c2)
381		}
382		c1, _ := r.Compartment("C1")
383		if c1.UsedWeight != 0 || c1.RemainingWeight != 100 || len(c1.Cargo) != 0 {
384			t.Fatalf("拒绝后 C1 应保持清空: %+v", c1)
385		}
386		g2, _ := r.Cargo("G2")
387		if !g2.Loaded || g2.CompartmentID != "C2" || g2.Weight != 40 {
388			t.Fatalf("G2 应保持原状留在 C2: %+v", g2)
389		}
390	
391		// 失败不占用编号：同一编号 A2 再次提交仍得到同样的重复操作错误，
392		// 而不是“调整编号冲突”，重量仍不重复占用。
393		res2, err2 := r.Adjust("A2", ops)
394		se2 := requireError(t, err2, ErrDuplicateOp)
395		if res2 != nil {
396			t.Fatalf("失败的调整不应占用编号，也不应返回成功结果: %+v", res2)
397		}
398		if se2.ID != "G1" || se2.AdjustmentID != "A2" {
399			t.Fatalf("再次提交应仍为指出 G1、携带 A2 的重复操作: %+v", se2)
400		}
401		c2, _ = r.Compartment("C2")
402		if c2.UsedWeight != 70 || c2.RemainingWeight != 30 ||
403			!reflect.DeepEqual(cargoIDs(*c2), []string{"G1", "G2"}) {
404			t.Fatalf("再次失败后 C2 重量与清单应保持不变: %+v", c2)
405		}
406	
407		// 移动与失败提交都不能改写保存下来的旧预览快照。
408		assertStaleMoveSnapshot(t, old)
409	}
410

